--
-- Table structure for table `application_usage`
--

DROP TABLE IF EXISTS `application_usage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `application_usage` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint(20) unsigned NOT NULL,
  `computer_id` bigint(20) unsigned NOT NULL,
  `activity_log_id` bigint(20) unsigned DEFAULT NULL,
  `application_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `executable` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `window_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `session_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `productivity` enum('productive','unproductive','neutral') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'neutral',
  `used_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `ended_at` timestamp NULL DEFAULT NULL,
  `duration_seconds` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `application_usage_computer_id_session_id_unique` (`computer_id`,`session_id`),
  KEY `application_usage_activity_log_id_foreign` (`activity_log_id`),
  KEY `application_usage_employee_id_used_at_index` (`employee_id`,`used_at`),
  KEY `application_usage_computer_id_used_at_index` (`computer_id`,`used_at`),
  KEY `application_usage_application_name_index` (`application_name`),
  KEY `application_usage_application_name_used_at_index` (`application_name`,`used_at`),
  CONSTRAINT `application_usage_activity_log_id_foreign` FOREIGN KEY (`activity_log_id`) REFERENCES `activity_logs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `application_usage_computer_id_foreign` FOREIGN KEY (`computer_id`) REFERENCES `computers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `application_usage_employee_id_foreign` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6904 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

